// src/ai/learning/learning-profile.ts
// Personalised learning from the player's own recorded mistakes. Pure logic; storage is handled separately.
// Every practice item is a general mission-management lesson, and none is generated by a model.
// NO React, Zustand, or Phaser imports.

import type { ErrorItem, ErrorResource } from '../errors/error-center'

export const PROFILE_VERSION = 1

export interface LearningProfile {
  readonly version: typeof PROFILE_VERSION
  /** Mistake counts per resource, across every recorded mission. */
  readonly mistakes: Readonly<Partial<Record<ErrorResource, number>>>
  /** Total decisions and optimal decisions across missions, used for the skill view. */
  readonly decisions: number
  readonly optimalDecisions: number
  /** Keys of missions already recorded, so reopening the debrief never double-counts. */
  readonly recordedMissions: readonly string[]
}

export const EMPTY_PROFILE: LearningProfile = {
  version: PROFILE_VERSION,
  mistakes: {},
  decisions: 0,
  optimalDecisions: 0,
  recordedMissions: [],
}

/** Parses stored JSON. Anything unexpected becomes an empty profile rather than an error. */
export function parseProfile(raw: string | null): LearningProfile {
  if (raw === null) return EMPTY_PROFILE
  try {
    const data = JSON.parse(raw) as Partial<LearningProfile>
    if (data.version !== PROFILE_VERSION) return EMPTY_PROFILE
    return {
      version: PROFILE_VERSION,
      mistakes: typeof data.mistakes === 'object' && data.mistakes !== null ? data.mistakes : {},
      decisions: Number.isFinite(data.decisions) ? Number(data.decisions) : 0,
      optimalDecisions: Number.isFinite(data.optimalDecisions) ? Number(data.optimalDecisions) : 0,
      recordedMissions: Array.isArray(data.recordedMissions)
        ? data.recordedMissions.filter((x): x is string => typeof x === 'string')
        : [],
    }
  } catch {
    return EMPTY_PROFILE
  }
}

/** Adds one finished mission. A mission key that was already recorded is ignored. */
export function recordMission(
  profile: LearningProfile,
  missionKey: string,
  items: readonly ErrorItem[],
  decisions: number,
  optimalDecisions: number,
): LearningProfile {
  if (profile.recordedMissions.includes(missionKey)) return profile
  const mistakes: Partial<Record<ErrorResource, number>> = { ...profile.mistakes }
  for (const item of items) {
    // Only the player's own decisions count as habits. Engine faults are shown in the debrief, not counted here.
    if (!item.id.startsWith('decision:')) continue
    mistakes[item.resource] = (mistakes[item.resource] ?? 0) + 1
  }
  return {
    version: PROFILE_VERSION,
    mistakes,
    decisions: profile.decisions + decisions,
    optimalDecisions: profile.optimalDecisions + optimalDecisions,
    recordedMissions: [...profile.recordedMissions, missionKey],
  }
}

/** Resources where the player has repeated the same kind of mistake, most frequent first. */
export function repeatedMistakes(profile: LearningProfile, threshold = 2): ErrorResource[] {
  return (Object.keys(profile.mistakes) as ErrorResource[])
    .filter((r) => (profile.mistakes[r] ?? 0) >= threshold)
    .sort((a, b) => (profile.mistakes[b] ?? 0) - (profile.mistakes[a] ?? 0))
}

/** Share of optimal decisions, or null when there is no data yet. */
export function optimalRate(profile: LearningProfile): number | null {
  if (profile.decisions === 0) return null
  return Math.round((profile.optimalDecisions / profile.decisions) * 100)
}

export interface PracticeItem {
  readonly resource: ErrorResource
  readonly question: string
  readonly options: readonly string[]
  readonly correctIndex: number
  readonly explanation: string
}

/** A small bank of general lessons, one per resource. */
export const PRACTICE_BANK: readonly PracticeItem[] = [
  {
    resource: 'oxygen',
    question: 'Oxygen and power are both falling. Which system do you protect first?',
    options: ['Crew entertainment', 'Oxygen generation', 'Lab experiments', 'Surface rover'],
    correctIndex: 1,
    explanation: 'Oxygen is life support. Without it the crew cannot survive for long, so it comes before anything else.',
  },
  {
    resource: 'water',
    question: 'Water is low and the recycler is running at reduced output. What is the best first action?',
    options: ['Increase hygiene water use', 'Reduce non-essential water use', 'Flood the crops', 'Ignore it until the next day'],
    correctIndex: 1,
    explanation: 'Cutting non-essential use protects drinking water while recovery continues.',
  },
  {
    resource: 'food',
    question: 'Food supplies will last 6 days at the current rate, and resupply arrives in 10 days. What should you do?',
    options: ['Keep the current ration', 'Start rationing now', 'Double the meals', 'Wait for the last day'],
    correctIndex: 1,
    explanation: 'Rationing early spreads the shortfall over more days. Waiting leaves less time to act.',
  },
  {
    resource: 'energy',
    question: 'Power is critical during a dust storm. Which loads do you switch off first?',
    options: ['Life support', 'Communications', 'Non-essential labs and lighting', 'Heaters for the habitat'],
    correctIndex: 2,
    explanation: 'Non-essential loads are shed first. Life support and communications are kept running.',
  },
  {
    resource: 'radiation',
    question: 'A solar storm warning arrives. Where should the crew shelter?',
    options: ['Outside on the surface', 'In the best-shielded area of the habitat', 'In the airlock', 'In the lab with the windows open'],
    correctIndex: 1,
    explanation: 'Dense shielding in the habitat reduces the dose. Surface operations are postponed during the storm.',
  },
  {
    resource: 'decision',
    question: 'An event offers a quick option that saves time now but risks a resource later. How do you decide?',
    options: ['Always pick the fastest option', 'Check the resource impact first', 'Pick the option with the most text', 'Let the crew vote'],
    correctIndex: 1,
    explanation: 'Checking the impact on resources before choosing prevents problems that appear days later.',
  },
]

/** Practice for repeated weaknesses first, then general practice. */
export function practiceFor(profile: LearningProfile, limit = 3): PracticeItem[] {
  const weak = repeatedMistakes(profile)
  const picked = PRACTICE_BANK.filter((p) => weak.includes(p.resource))
  const rest = PRACTICE_BANK.filter((p) => !weak.includes(p.resource))
  return [...picked, ...rest].slice(0, limit)
}
